using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using Microsoft.Win32;
namespace Quill.Windows;
public static class Theme {
 public static FontFamily Sans { get; } = new(new Uri("pack://application:,,,/"), "./Assets/Fonts/#IBM Plex Sans");
 public static FontFamily Serif { get; } = new(new Uri("pack://application:,,,/"), "./Assets/Fonts/#IBM Plex Serif");
 public static SolidColorBrush Hex(string value) => new((Color)ColorConverter.ConvertFromString(value));
 public static void Apply(string preference) {
  bool dark = preference == "Dark" || preference == "Match system" && (Registry.GetValue(@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize", "AppsUseLightTheme", 1) as int? ?? 1) == 0;
  var r = Application.Current.Resources;
  foreach (var entry in new Dictionary<string,string> { ["Paper"] = dark ? "#0F1117" : "#EFF1F6", ["Surface"] = dark ? "#191B23" : "#FFFFFF", ["Sunken"] = dark ? "#20232D" : "#F6F7FB", ["Ink"] = dark ? "#ECEDF3" : "#1C1B33", ["Muted"] = dark ? "#9A9DAC" : "#6E6E81", ["Line"] = dark ? "#363A48" : "#E3E5EE", ["Brand"] = dark ? "#5A4FE0" : "#4A3FD0", ["BrandInk"] = dark ? "#A79BFF" : "#3A2EA3", ["BrandSoft"] = dark ? "#26233F" : "#ECEAFB", ["Gold"] = "#E0A03A", ["GoldDeep"] = dark ? "#F0C277" : "#8A5A12", ["GoldSoft"] = dark ? "#332919" : "#FBEFD6", ["Error"] = dark ? "#E8635B" : "#D6453D" }) r[entry.Key] = Hex(entry.Value);
  var text = new Style(typeof(TextBlock)); text.Setters.Add(new Setter(TextBlock.FontFamilyProperty, Sans)); text.Setters.Add(new Setter(TextBlock.ForegroundProperty, new DynamicResourceExtension("Ink"))); text.Setters.Add(new Setter(TextBlock.TextWrappingProperty, TextWrapping.Wrap)); r[typeof(TextBlock)] = text;
  var button = new Style(typeof(Button)); button.Setters.Add(new Setter(Control.FontFamilyProperty, Sans)); button.Setters.Add(new Setter(Control.FontSizeProperty, 15.0)); button.Setters.Add(new Setter(Control.FontWeightProperty, FontWeights.SemiBold)); button.Setters.Add(new Setter(Control.PaddingProperty, new Thickness(16,11,16,11))); button.Setters.Add(new Setter(FrameworkElement.MinHeightProperty, 46.0)); button.Setters.Add(new Setter(Control.BackgroundProperty, new DynamicResourceExtension("BrandSoft"))); button.Setters.Add(new Setter(Control.ForegroundProperty, new DynamicResourceExtension("BrandInk"))); button.Setters.Add(new Setter(Control.BorderThicknessProperty, new Thickness(0))); button.Setters.Add(new Setter(FrameworkElement.MarginProperty, new Thickness(0,4,8,4)));
  var template = new ControlTemplate(typeof(Button)); var border = new FrameworkElementFactory(typeof(Border)); border.SetValue(Border.CornerRadiusProperty, new CornerRadius(14)); border.SetBinding(Border.BackgroundProperty, new System.Windows.Data.Binding("Background") { RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent) }); var content = new FrameworkElementFactory(typeof(ContentPresenter)); content.SetValue(ContentPresenter.HorizontalAlignmentProperty, HorizontalAlignment.Center); content.SetValue(ContentPresenter.VerticalAlignmentProperty, VerticalAlignment.Center); content.SetBinding(ContentPresenter.MarginProperty, new System.Windows.Data.Binding("Padding") { RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent) }); border.AppendChild(content); template.VisualTree = border; button.Setters.Add(new Setter(Control.TemplateProperty, template));
  var hover = new Trigger { Property = UIElement.IsMouseOverProperty, Value = true }; hover.Setters.Add(new Setter(UIElement.OpacityProperty, 0.85)); button.Triggers.Add(hover); var disabled = new Trigger { Property = UIElement.IsEnabledProperty, Value = false }; disabled.Setters.Add(new Setter(UIElement.OpacityProperty, 0.45)); button.Triggers.Add(disabled); r[typeof(Button)] = button;
  foreach (var type in new[] { typeof(TextBox), typeof(PasswordBox), typeof(ComboBox) }) { var style = new Style(type); style.Setters.Add(new Setter(Control.FontFamilyProperty, Sans)); style.Setters.Add(new Setter(Control.FontSizeProperty, 16.0)); style.Setters.Add(new Setter(Control.PaddingProperty, new Thickness(12,10,12,10))); style.Setters.Add(new Setter(FrameworkElement.MinHeightProperty, 46.0)); style.Setters.Add(new Setter(Control.BackgroundProperty, new DynamicResourceExtension("Surface"))); style.Setters.Add(new Setter(Control.ForegroundProperty, new DynamicResourceExtension("Ink"))); style.Setters.Add(new Setter(Control.BorderBrushProperty, new DynamicResourceExtension("Line"))); style.Setters.Add(new Setter(FrameworkElement.MarginProperty, new Thickness(0,4,0,10))); r[type] = style; }
  var check = new Style(typeof(CheckBox)); check.Setters.Add(new Setter(Control.FontFamilyProperty, Sans)); check.Setters.Add(new Setter(Control.ForegroundProperty, new DynamicResourceExtension("Ink"))); check.Setters.Add(new Setter(Control.FontSizeProperty, 15.0)); check.Setters.Add(new Setter(Control.PaddingProperty, new Thickness(8))); check.Setters.Add(new Setter(FrameworkElement.MinHeightProperty, 44.0)); check.Setters.Add(new Setter(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center)); r[typeof(CheckBox)] = check;
 }
}
